using DialogEdit;
using ProjectTower.gamestate;
using ProjectTower.player;
namespace ProjectTower.menu.levels;
public class Options : MenuLevel
{
	public const int VIDEO = 0;
	public const int AUDIO = 1;
	public const int GAME = 2;
	public const int LANGUAGE = 3;
	public const int BACK = 4;
	public Options()
	{
		title = LocStrings.GetLocString(229);
		showTitle = true;
		item = new MenuItem[5]
		{
			new MenuItem(0, LocStrings.GetLocStr(230)),
			new MenuItem(1, LocStrings.GetLocStr(225)),
			new MenuItem(2, LocStrings.GetLocStr(243)),
			new MenuItem(2, LocStrings.GetLocStr(325)),
			new MenuItem(4, LocStrings.GetLocStr(223))
		};
	}
	public override void Select(Player p, int o)
	{
		switch (selected)
		{
		case 0:
			((VideoOptions)p.menuMgr.menuLevel[20]).Init();
			p.menuMgr.DoLevelTrans(20);
			break;
		case 3:
			((LanguageOptions)p.menuMgr.menuLevel[30]).Init();
			p.menuMgr.DoLevelTrans(30);
			break;
		case 1:
			((AudioOptions)p.menuMgr.menuLevel[28]).Init();
			p.menuMgr.DoLevelTrans(28);
			break;
		case 2:
			((GameOptions)p.menuMgr.menuLevel[32]).Init();
			p.menuMgr.DoLevelTrans(32);
			break;
		case 4:
			if (GameStateManager.gameState == 1)
			{
				p.menuMgr.DoLevelTrans(17);
			}
			else
			{
				p.menuMgr.DoLevelTrans(1);
			}
			break;
		}
		base.Select(p, o);
	}
	public override void Cancel(Player p, int o)
	{
		if (GameStateManager.gameState == 1)
		{
			p.menuMgr.DoLevelTrans(17);
		}
		else
		{
			p.menuMgr.DoLevelTrans(1);
		}
		base.Cancel(p, o);
	}
}
