=== PressStart
using DialogEdit;
using ProjectTower.gamestate;
using ProjectTower.player;
using ProjectTower.steam;
using ProjectTower.steam.ugc;
namespace ProjectTower.menu.levels;
public class PressStart : MenuLevel
{
	public PressStart()
	{
		item = new MenuItem[1]
		{
			new MenuItem(0, LocStrings.GetLocStr(317))
		};
		heavyConfirm = true;
	}
	public override void Select(Player p, int o)
	{
		p.menuMgr.DoLevelTrans(1);
		for (int i = 0; i < PlayerMgr.player.Length; i++)
		{
			PlayerMgr.player[i].Deactivate();
		}
		p.Activate(p.gamepadIdx);
		GameStateManager.mainPlayerIdx = p.ID;
		GameStateManager.coopPlayerIdx = -1;
		GameStateManager.pvpMode = false;
		Game1.charSaveList.Init(PlayerMgr.GetMainPlayer());
		if (UGCManager.state == 0)
		{
			UGCManager.state = 1;
			SteamServiceMgr.DiscoverUGC();
		}
		if (Game1.charSaveList.HasSaves())
		{
			p.menuMgr.menuLevel[1].selected = 1;
		}
		base.Select(p, o);
	}
}
=== QuitToDesktop
using System.Text;
using DialogEdit;
using ProjectTower.character;
using ProjectTower.gamestate;
using ProjectTower.hud;
using ProjectTower.player;
namespace ProjectTower.menu.levels;
public class QuitToDesktop : MenuLevel
{
	public const int YES = 0;
	public const int NO = 1;
	public static bool needsSaved;
	public QuitToDesktop(Player p)
	{
		title = new StringBuilder(LocStrings.GetLocStr(236));
		showTitle = true;
		item = new MenuItem[2]
		{
			new MenuItem(0, LocStrings.GetLocStr(208)),
			new MenuItem(1, LocStrings.GetLocStr(209))
		};
		infos = WordWrap.Wrap(p, LocStrings.GetLocStr(237) + "\r\n\r\n" + LocStrings.GetLocStr(1123), 30, 3);
	}
	public override void Select(Player p, int o)
	{
		switch (selected)
		{
		case 0:
		{
			p.menuMgr.DoLevelTrans(1);
			p.playerInv.active = false;
			Character playerCharacter = CharMgr.GetPlayerCharacter(p);
			if (playerCharacter != null)
			{
				p.WriteCharSave(playerCharacter);
			}
			if (GameStateManager.coopPlayerIdx > -1)
			{
				Player obj = PlayerMgr.player[(GameStateManager.coopPlayerIdx == p.ID) ? GameStateManager.mainPlayerIdx : GameStateManager.coopPlayerIdx];
				Character playerCharacter2 = CharMgr.GetPlayerCharacter(obj);
				obj.WriteCharSave(playerCharacter2);
			}
			GameStateManager.quitFrame = 1f;
			break;
		}
		case 1:
			p.menuMgr.DoLevelTrans(17);
			break;
		}
		base.Select(p, o);
	}
	public override void Cancel(Player p, int o)
	{
		p.menuMgr.DoLevelTrans(17);
		base.Cancel(p, o);
	}
}
