		bool result = false;
		if (selected)
		{
			Keys[] pressedKeys = ks.GetPressedKeys();
			for (int i = 0; i < pressedKeys.Length; i++)
			{
				Keys keys = pressedKeys[i];
				bool flag = true;
				Keys[] pressedKeys2 = pks.GetPressedKeys();
				for (int j = 0; j < pressedKeys2.Length; j++)
				{
					if (pressedKeys2[j] == keys)
					{
						flag = false;
					}
				}
				if (!flag)
				{
					continue;
				}
				int length = SeedBuffer.Length;
				switch (keys)
				{
				case Keys.D0:
				case Keys.D1:
				case Keys.D2:
				case Keys.D3:
				case Keys.D4:
				case Keys.D5:
				case Keys.D6:
				case Keys.D7:
				case Keys.D8:
				case Keys.D9:
					if (length < num)
					{
						SeedBuffer.Append(keys.ToString().Remove(0, 1));
					}
					break;
				case Keys.NumPad0:
				case Keys.NumPad1:
				case Keys.NumPad2:
				case Keys.NumPad3:
				case Keys.NumPad4:
				case Keys.NumPad5:
				case Keys.NumPad6:
				case Keys.NumPad7:
				case Keys.NumPad8:
				case Keys.NumPad9:
					if (length < num)
					{
						SeedBuffer.Append(keys.ToString().Remove(0, 6));
					}
					break;
				case Keys.Back:
					if (length > 0)
					{
						SeedBuffer.Remove(SeedBuffer.Length - 1, 1);
					}
					break;
				case Keys.Enter:
					return result;
				}
			}
		}
		return result;
	}
	public override void SelectedUpdate(Player p)
	{
		KeyboardState keyboardState = GlobalInputMgr.GetKeyboardState();
		UpdateSeed(p, keyboardState, pks, selected == 0, initialNameScreen: true);
		pks = keyboardState;
		if (p.menuMgr.keys.GetUp(GameStateManager.mainPlayerIdx) > -1 || p.menuMgr.keys.GetDown(GameStateManager.mainPlayerIdx) > -1)
		{
			if (selected == 0)
			{
				selected = 1;
			}
			else
			{
				selected = 0;
			}
			Sound.PlaySelect();
		}
		((CreateCharacter)p.menuMgr.menuLevel[3]).SelectedUpdate(p);
		base.SelectedUpdate(p);
	}
	public override void Select(Player p, int o)
	{
		switch (selected)
		{
		case 0:
			selected = 1;
			Sound.PlaySelect();
			break;
		case 1:
			SetSeedValue(p);
			p.menuMgr.DoSpecialTrans(0);
			break;
		}
		base.Select(p, o);
	}
	public override void Cancel(Player p, int o)
	{
		Sound.PlayCancel();
		p.menuMgr.DoLevelTrans(3);
		base.Cancel(p, o);
	}
	public static void SetSeedValue(Player p)
	{
		if (p.menuMgr.transMode != 0)
		{
			return;
		}
		if (uint.TryParse(SeedBuffer.ToString(), out var result))
		{
			int seed = (int)result;
			if (result > int.MaxValue)
			{
				seed = int.MaxValue;
			}
			p.seed = seed;
		}
		p.menuMgr.DoSpecialTrans(0);
		Sound.PlayConfirm();
	}
