	public static List<Point> GetResolutions(GraphicsDevice dev)
	{
		List<Point> list = new List<Point>();
		DisplayModeCollection supportedDisplayModes = dev.Adapter.SupportedDisplayModes;
		foreach (DisplayMode item in supportedDisplayModes)
		{
			if (item.Width >= 1280)
			{
				list.Add(new Point(item.Width, item.Height));
			}
		}
		if (list.Count == 0)
		{
			foreach (DisplayMode item2 in supportedDisplayModes)
			{
				list.Add(new Point(item2.Width, item2.Height));
			}
		}
		return list;
	}
	public void Init()
	{
		List<string> list = new List<string>();
		displayModes = GetResolutions(SpriteTools.sprite.GraphicsDevice);
		int selX = 0;
		for (int i = 0; i < displayModes.Count; i++)
		{
			if (ConfigMgr.displayWidth == displayModes[i].X && ConfigMgr.displayHeight == displayModes[i].Y)
			{
				selX = i;
			}
			list.Add(displayModes[i].X + " x " + displayModes[i].Y);
		}
		item[0] = new MenuItem(0, list.ToArray());
		item[0].selX = selX;
		item[1].selX = ConfigMgr.fullScreen;
		item[3].selX = ((ConfigMgr.vSync == 0) ? 1 : 0);
		item[2].selX = GetSelectIdxFrameRate(ConfigMgr.frameRateCap);
	}
	public override void SelectedUpdate(Player p)
	{
		base.SelectedUpdate(p);
	}
	public override void Select(Player p, int o)
	{
		switch (selected)
		{
		case 4:
		{
			int num = 0;
			int num2 = 0;
			bool flag = true;
			int num3 = 60;
			num = displayModes[item[0].selX].X;
			num2 = displayModes[item[0].selX].Y;
			flag = item[3].selX == 0;
			num3 = GetFrameRateSelect(item[2].selX);
			if ((num != 0 && num2 != 0) || vsyncOn != flag || ConfigMgr.frameRateCap != num3)
			{
				((AcceptVideo)p.menuMgr.menuLevel[21]).Init(num, num2, item[1].selX, flag, num3);
				p.menuMgr.DoLevelTrans(21);
			}
			break;
		}
		case 5:
			if (GameStateManager.gameState == 1)
			{
				p.menuMgr.DoLevelTrans(17);
			}
			else
			{
				p.menuMgr.DoLevelTrans(19);
			}
			break;
		}
		base.Select(p, o);
	}
	public override void Cancel(Player p, int o)
	{
		if (GameStateManager.gameState == 1)
		{
			p.menuMgr.DoLevelTrans(17);
		}
		else
		{
			p.menuMgr.DoLevelTrans(19);
		}
		base.Cancel(p, o);
	}
	private int GetFrameRateSelect(int menuIdx)
	{
		return menuIdx switch
		{
			0 => 60, 
			1 => 72, 
			2 => 85, 
			3 => 90, 
			4 => 100, 
			5 => 120, 
			6 => 144, 
			7 => 165, 
			8 => 170, 
			9 => 180, 
			10 => 240, 
			11 => 360, 
			_ => 60, 
		};
	}
	private int GetSelectIdxFrameRate(int framerate)
	{
		return framerate switch
		{
			60 => 0, 
			72 => 1, 
			85 => 2, 
			90 => 3, 
			100 => 4, 
			120 => 5, 
			144 => 6, 
			165 => 7, 
			170 => 8, 
			180 => 9, 
			240 => 10, 
			360 => 11, 
			_ => 60, 
		};
	}
