using System.IO;
using ProjectTower.character;
using ProjectTower.player;
namespace ProjectTower.menu;
public class CharSaveChar
{
	public Player p;
	public Character c;
	public int ID;
	public bool exists;
	public bool challengeMode;
	public bool deadForever;
	public CharSaveChar(int ID)
	{
		p = new Player(0);
		c = new Character(0);
		c.Init("hero", default, 0, 0, 0);
		c.playerIdx = -1;
		exists = false;
		this.ID = ID;
	}
	public void Read(BinaryReader reader)
	{
		challengeMode = false;
		exists = true;
		p.Read(reader, c.equipment);
		for (int i = 0; i < 7; i++)
		{
			if (p.challenge.category[i].activeChallenge > -1 && i < 5)
			{
				challengeMode = true;
			}
		}
		if (p.challenge.category[0].activeChallenge == 0 && p.flags.Contains("_#_DED4EVAR_#_"))
		{
			deadForever = true;
		}
	}
	public void ReadRandomizerExtension(BinaryReader reader)
	{
		p.ReadRandomizerExt(reader);
	}
	internal void Load(Player p, CharEquipment charEquipment)
	{
		p.CopyFrom(this.p, copyID: false);
		charEquipment.CopyFrom(c.equipment);
	}
}
