using System.Text;
using System.Threading;
using ProjectTower.player;
using ProjectTower.storage;
namespace ProjectTower.menu;
public class CharSaveList
{
	public CharSaveChar[] charSaveChar;
	public static string[] saveName;
	public static string[] randName;
	public const int TOTAL_CHAR_SAVE_CHARS = 10;
	public bool busy;
	public bool inited;
	public StringBuilder charSaveSemaphore;
	public const int CHAR_SAVE_TICKS = 1000;
	public CharSaveList()
	{
		charSaveSemaphore = new StringBuilder("save");
	}
	public void InitFields()
	{
		if (Monitor.TryEnter(charSaveSemaphore, 1000))
		{
			try
			{
				charSaveChar = new CharSaveChar[10];
				for (int i = 0; i < charSaveChar.Length; i++)
				{
					charSaveChar[i] = new CharSaveChar(i);
				}
			}
			finally
			{
				Monitor.Exit(charSaveSemaphore);
			}
		}
		saveName = new string[10];
		randName = new string[10];
		for (int j = 0; j < saveName.Length; j++)
		{
			saveName[j] = "dat" + j + ".slv";
			randName[j] = "dat" + j + ".rand";
		}
	}
	public void Init(Player p)
	{
		InitFields();
		StorageJobMgr.AddJob(2, p.ID, -1);
	}
	internal int GetFreeSlot()
	{
		if (Monitor.TryEnter(charSaveSemaphore, 1000))
		{
			int result = -1;
			try
			{
				for (int i = 0; i < charSaveChar.Length; i++)
				{
					if (!charSaveChar[i].exists)
					{
						result = i;
						break;
					}
				}
			}
			finally
			{
				Monitor.Exit(charSaveSemaphore);
			}
			return result;
		}
		return -1;
	}
	internal bool HasSaves()
	{
		if (Monitor.TryEnter(charSaveSemaphore, 1000))
		{
			bool result = false;
			try
			{
				for (int i = 0; i < charSaveChar.Length; i++)
				{
					if (charSaveChar[i].exists)
					{
						result = true;
					}
				}
				return result;
			}
			finally
			{
				Monitor.Exit(charSaveSemaphore);
			}
		}
		return false;
	}
}
