	public void DoLevelTrans(int level)
	{
		if (transMode == 0)
		{
			transLevel = level;
			transMode = 1;
			transFrame = 0f;
			if (menuLevel[level].showParent == curLev)
			{
				curLev = level;
				transMode = 2;
				transFrame = 0f;
			}
		}
	}
	public void DoSpecialTrans(int level)
	{
		if (transMode == 0)
		{
			transSpecial = level;
			transMode = 3;
			transFrame = 0f;
		}
	}
	public void Update()
	{
		if (Text.arrowHighlight > 0f)
		{
			Text.arrowHighlight -= Game1.realTime;
			if (Text.arrowHighlight < 0f)
			{
				Text.arrowHighlight = 0f;
			}
		}
		if (Text.arrowHighlight < 0f)
		{
			Text.arrowHighlight += Game1.realTime;
			if (Text.arrowHighlight > 0f)
			{
				Text.arrowHighlight = 0f;
			}
		}
		if (GuideStuff.keyboardActive)
		{
			GuideStuff.keyboardFrame += Game1.frameTime;
			if (GuideStuff.keyboardFrame > (float)Math.PI * 2f)
			{
				GuideStuff.keyboardFrame -= (float)Math.PI * 2f;
			}
		}
		switch (transMode)
		{
		case 1:
			transFrame += Game1.frameTime;
			if (menuLevel[curLev].showParent == transLevel || (menuLevel[transLevel].showParent > -1 && menuLevel[transLevel].showParent == menuLevel[curLev].showParent))
			{
				transFrame += Game1.frameTime * 3f;
			}
			if (GameStateManager.gameState == 1)
			{
				transFrame += Game1.frameTime * 3f;
			}
			if (!(transFrame > 1f))
			{
				break;
			}
			if (menuLevel[curLev].showParent == transLevel)
			{
				curLev = transLevel;
				transMode = 0;
				transFrame = 0f;
				break;
			}
			if (GameStateManager.gameState == 2)
			{
				if (transLevel == 3)
				{
					GameStateManager.gameState = 0;
				}
			}
			else if (GameStateManager.gameState == 0 && transLevel == 1)
			{
				GameStateManager.gameState = 2;
				LogoRender.drawFrame = -1f;
				LogoRender.drawAlpha = 0f;
			}
			curLev = transLevel;
			transFrame = 0f;
			transMode = 2;
			menuLevel[curLev].scroll = 0f;
			break;
		case 3:
			transFrame += Game1.frameTime;
			if (transFrame > 1f)
			{
				curLev = transLevel;
				transFrame = 0f;
				transMode = 4;
				switch (transSpecial)
				{
				case 0:
					NewGameManager.NewGame(p);
					break;
				case 1:
					NewGameManager.LoadGame(p, GameStateManager.GetMainPlayer().dataIdx);
					break;
				}
			}
			break;
		case 2:
		case 4:
			if (GameStateManager.gameState == 2 || GameStateManager.gameState == 0)
			{
				menuLevel[curLev].selected = 0;
				menuLevel[curLev].scroll = (menuLevel[curLev].selectedScroll = 100f);
				for (int i = 0; i < menuLevel[curLev].item.Length; i++)
				{
					if (i == 0)
					{
						menuLevel[curLev].item[i].sel = 1f;
					}
					else
					{
						menuLevel[curLev].item[i].sel = 0f;
					}
				}
			}
			if (transMode == 2 && GameStateManager.gameState == 2)
			{
				if (LogoRender.drawFrame > 3f)
				{
					transFrame += Game1.frameTime;
				}
			}
			else
			{
				transFrame += Game1.frameTime;
			}
			if (GameStateManager.gameState == 1)
			{
				transFrame += Game1.frameTime * 3f;
				if (menuLevel[curLev].optionScroll)
				{
					menuLevel[curLev].scroll = (menuLevel[curLev].selectedScroll = 520f * ScrollManager.GetHdFactor());
					menuLevel[curLev].selected = 0;
				}
			}
			if (transMode == 2 && menuLevel[curLev].showParent > -1)
			{
				transFrame += Game1.frameTime * 3f;
			}
			if (transFrame > 1f)
			{
				transMode = 0;
			}
			break;
		}
		for (int j = 0; j < menuLevel.Length; j++)
		{
			menuLevel[j].Update(p, j);
		}
	}
	internal void Draw(float scale, Rectangle dRect)
	{
		if (DebugMgr.trailerMode)
		{
			return;
		}
		try
		{
			for (int i = 0; i < menuLevel.Length; i++)
			{
				if (menuLevel[i].alpha > 0f)
				{
					menuLevel[i].Draw(p, scale, dRect);
				}
			}
		}
		catch (Exception ex)
		{
			GameConsole.WriteLine(ex.StackTrace);
		}
		float hdFactor = ScrollManager.GetHdFactor();
		float num = 0f;
		if (transMode == 3)
		{
