					p.playerInv.UseMaterialDef(workItem[selItem].loot.category, workItem[selItem].loot.catalogIdx);
				p.creedLevel[sanctuary.creed] += workItem[selItem].devotion;
				if (p.creedLevel[sanctuary.creed] >= 7)
					Achievements.AwardAchievement(34);
					p.creedLevel[sanctuary.creed] = 7;
				p.creedUnlocks[sanctuary.creed, ((WorkUpgrade)p.dialog.menuMgr.menuLevel[23]).selItem]++;
				string text = WorkTitle(sanctuary, workItem[selItem]);
