			p.creedUnlocks[creed, i] = 0;
		int num = 0;
		while (true)
			num++;
			bool flag = false;
			for (int j = 0; j < p.flags.Count; j++)
				if (!p.flags[j].StartsWith("#wi#_"))
					continue;
				string value = p.flags[j].Substring("#wi#_".Length, 1);
				try
					if (Convert.ToInt32(value) == creed)
						GameConsole.WriteLine("Purged " + p.flags[j] + ".");
						p.flags.RemoveAt(j);
						flag = true;
						break;
				catch
			if (!flag)
				break;
			if (num > 100)
				GameConsole.WriteLine("Overload.");
				break;
		GameConsole.WriteLine("Purging complete.");
