	public static void DoDialog(int dialogIdx, int nodeIdx, Player p, int npcIdx)
	{
		if (dialogIdx < 0 || dialogIdx > DialogMgr.dialogList.Length - 1)
		{
			return;
		}
		NPCDialog nPCDialog = DialogMgr.dialogList[dialogIdx];
		if (nodeIdx < 0 || nodeIdx > nPCDialog.nodeList.Length - 1)
		{
			return;
		}
		DialogNode dialogNode = nPCDialog.nodeList[nodeIdx];
		for (int i = 0; i < dialogNode.precheckFlagStr.Length; i++)
		{
			if (dialogNode.precheckFlagStr[i] != "" && PlayerMgr.GetMainPlayerFlag(dialogNode.precheckFlagStr[i]))
			{
				nodeIdx = nPCDialog.GetNodeIdx(dialogNode.precheckFlagGoto[i]);
				if (nodeIdx > -1)
				{
					dialogNode = nPCDialog.nodeList[nodeIdx];
					i = -1;
				}
			}
		}
		p.dialog.dialogCatIdx = dialogIdx;
		p.dialog.dialogCatNodeIdx = nodeIdx;
		if (dialogNode.postSetFlagStr != "")
		{
			PlayerMgr.SetMainPlayerFlag(dialogNode.postSetFlagStr);
		}
		if (dialogNode.text[Game1.language].text != null)
		{
			p.dialog.talkieFrame = 0f;
			p.dialog.Activate(dialogNode.text[Game1.language].text, npcIdx);
		}
		else if (dialogNode.option != null)
		{
			p.dialog.npcIdx = npcIdx;
			p.dialog.menuMgr.Activate(14);
			((NPCQuestion)p.dialog.menuMgr.menuLevel[14]).Init(dialogNode.name, dialogNode.option, p);
		}
		else if (dialogNode.storeScript != null)
		{
			NPCStore.DoStore(p, dialogNode.storeScript);
		}
		else
		{
			KillDialog(p);
		}
	}
	private static string GetTalkPhase(string flag)
	{
		try
		{
			string[] array = flag.Split(new string[1] { "\n" }, StringSplitOptions.RemoveEmptyEntries);
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i].Contains("talkphase "))
				{
					return array[i].Split(' ')[1];
				}
			}
		}
		catch
		{
		}
		return "talk";
	}
