	{
		PlayerDialog dialog = p.dialog;
		_ = p.dialog.menuMgr;
		NPCDialog nPCDialog = DialogMgr.dialogList[dialog.dialogCatIdx];
		if (dialog.dialogCatNodeIdx > -1)
		{
			DialogNode dialogNode = nPCDialog.nodeList[dialog.dialogCatNodeIdx];
			if (dialogNode.giveScript != null)
			{
				for (int i = 0; i < dialogNode.giveScript.Length; i++)
				{
					GiveItem(p, dialogNode.giveScript[i]);
				}
			}
			if (dialogNode.postGoto != "")
			{
				int nodeIdx = nPCDialog.GetNodeIdx(dialogNode.postGoto);
				DoDialog(dialog.dialogCatIdx, nodeIdx, p, p.dialog.npcIdx);
			}
			else if (dialogNode.option != null)
			{
				p.dialog.menuMgr.Activate(14);
				((NPCQuestion)p.dialog.menuMgr.menuLevel[14]).Init(dialogNode.name, dialogNode.option, p);
			}
			else if (dialogNode.storeScript != null)
			{
				NPCStore.DoStore(p, dialogNode.storeScript);
			}
			else
			{
				KillDialog(p);
			}
