		{
			array = item.Split('|');
		}
		for (int i = 0; i < dialogNode.option.Length; i++)
		{
			bool flag = false;
			if (dialogNode.option[i].text[0].Contains('|'))
			{
				string[] array2 = dialogNode.option[i].text[0].Split('|');
				if (array != null && array2[0] == array[0])
				{
					LootDef lDef = dialog.menuMgr.menuLevel[14].item[i].lDef;
