	private static void GiveItem(Player p, string item)
	{
		switch (item)
		{
		case "icon_iron":
			SetPlayerCreed(p, 1);
			break;
		case "icon_cleric":
			SetPlayerCreed(p, 2);
			break;
		case "icon_three":
			SetPlayerCreed(p, 3);
			break;
		case "icon_wood":
			SetPlayerCreed(p, 4);
			break;
		case "icon_dark":
			SetPlayerCreed(p, 5);
			break;
		case "icon_splendor":
			SetPlayerCreed(p, 6);
			break;
		case "icon_fool":
			SetPlayerCreed(p, 7);
			break;
		case "icon_fire":
			SetPlayerCreed(p, 8);
			break;
		case "icon_bones":
			SetPlayerCreed(p, 9);
			break;
		}
		InvLoot invLoot = new InvLoot();
		invLoot.InitFromName(item);
		int num = p.playerInv.Add(invLoot, autoSelect: true, 1);
		if (p.pickup == null)
		{
			p.pickup = new List<Player.PlayerPickup>();
			p.pickupFrame = 3f;
		}
		if (invLoot.category == 3 && LootCatalog.category[invLoot.category].loot[invLoot.catalogIdx].type == 2)
		{
			_ = p.dialog;
			_ = p.dialog.menuMgr;
			Character character = CharMgr.character[p.dialog.npcIdx];
			p.runeGetFrame = 8f;
			Character playerCharacter = CharMgr.GetPlayerCharacter(p);
			if (playerCharacter != null && character != null)
			{
				int nPCIdx = NPCMgr.GetNPCIdx(MonsterCatalog.catalog[character.monsterIdx]);
				if (nPCIdx > -1)
				{
					playerCharacter.face = NPCMgr.npc[nPCIdx].brandFire;
					character.face = 1 - playerCharacter.face;
				}
				playerCharacter.anim.SetAnimation("branded");
				switch (character.npcStyle)
				{
				case 2:
					character.anim.SetAnimation("jesterbrand");
					break;
				case 3:
					character.anim.SetAnimation("ledgebrand");
					break;
				default:
					character.anim.SetAnimation("noblesbrand");
					break;
				}
				character.draw.consumableIdx = 0;
			}
			p.runeImgIdx = LootCatalog.category[invLoot.category].loot[invLoot.catalogIdx].flags;
		}
		if (num > -1)
		{
			p.AddPickup(num, invLoot.category, invLoot.catalogIdx, 1);
			return;
		}
		Character playerCharacter2 = CharMgr.GetPlayerCharacter(p);
		if (playerCharacter2 != null)
		{
			MapMgr.pickupMgr.Drop(new string[1] { item }, playerCharacter2.loc + new Vector2(0f, -50f), null);
		}
	}
